const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const TILE=40, MAP=90, WORLD=MAP*TILE;
const ui={day:document.getElementById('day-count'),clock:document.getElementById('clock'),location:document.getElementById('location'),toast:document.getElementById('toast'),hint:document.getElementById('interact-hint'),inventory:document.getElementById('inventory')};
let W=0,H=0,dpr=1,camera={x:0,y:0},last=0,toastTimer=0,gameOn=false,ended=false,keys={},touch={},objects=[],ponds=[],particles=[],critters=[],gatheredTotal=0;
let state={x:WORLD/2,y:WORLD/2,day:1,minute:8*60,health:100,hunger:82,energy:92,mood:76,wood:0,stone:0,berries:2,mushroom:0,camp:false,played:0,gameTime:0};
const rand=(x,y,s=0)=>{let n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n)};
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function makeWorld(){
  objects=[];ponds=[{x:WORLD*.30,y:WORLD*.38,rx:160,ry:115},{x:WORLD*.69,y:WORLD*.65,rx:125,ry:155},{x:WORLD*.77,y:WORLD*.29,rx:85,ry:68}];
  const types=['tree','tree','tree','tree','rock','berry','berry','mushroom','flower','log'];
  for(let i=0;i<610;i++){let x=55+rand(i,3,7)*(WORLD-110),y=55+rand(i,9,13)*(WORLD-110);if(Math.hypot(x-WORLD/2,y-WORLD/2)<185)continue;
    if(ponds.some(p=>((x-p.x)/p.rx)**2+((y-p.y)/p.ry)**2<1.22))continue;
    if(Math.abs(x-y*.28-WORLD*.29)<75||Math.abs(x+y*.25-WORLD*.68)<58)continue;
    let type=types[Math.floor(rand(i,5,21)*types.length)];objects.push({x,y,type,alive:true,regrow:0,scale:.76+rand(i,1,55)*.62,seed:i});}
  for(let i=0;i<8;i++){let a=rand(i,11,45)*Math.PI*2,r=220+rand(i,12,17)*850;critters.push({x:WORLD/2+Math.cos(a)*r,y:WORLD/2+Math.sin(a)*r,angle:rand(i,33)*6.28,alive:true,scared:0,kind:i%2?'hare':'fox'})}
  // Little clearings around the starting meadow.
  for(let i=0;i<65;i++){let a=rand(i,61)*Math.PI*2,r=80+rand(i,62)*185;objects.push({x:WORLD/2+Math.cos(a)*r,y:WORLD/2+Math.sin(a)*r,type:['flower','flower','berry','log'][Math.floor(rand(i,63)*4)],alive:true,regrow:0,scale:.7+rand(i,64)*.5,seed:900+i})}
}
makeWorld();
function atWater(x,y){return ponds.some(p=>((x-p.x)/p.rx)**2+((y-p.y)/p.ry)**2<1)}
function isPath(x,y){return Math.abs(x-y*.28-WORLD*.29)<46||Math.abs(x+y*.25-WORLD*.68)<34}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
function nearObject(){let best=null,dist=100;for(const o of objects){if(!o.alive)continue;let d=Math.hypot(o.x-state.x,o.y-state.y);if(d<dist){dist=d;best=o}}if(state.camp){let d=Math.hypot(WORLD/2-state.x,WORLD/2-state.y);if(d<dist){dist=d;best={type:'camp',x:WORLD/2,y:WORLD/2}}}return best&&dist<83?best:null}
function safeNumber(x){return Math.round(x)}
function renderInv(){const items=[['🪵','wood',state.wood],['◈','stone',state.stone],['🍒','berry',state.berries],['🍄','mushroom',state.mushroom]];ui.inventory.innerHTML=items.map(([ico,n,count])=>`<div class="inv-slot ${count?'':'empty'}"><span class="inv-name">${n.toUpperCase()}</span><span class="inv-icon">${ico}</span><span class="inv-count">${count}</span></div>`).join('')}
function setMeter(id,value){const v=Math.max(0,Math.min(100,value));document.getElementById(id+'-bar').style.width=v+'%';document.getElementById(id+'-value').textContent=Math.round(v)+'%';const bar=document.getElementById(id+'-bar');if(id==='hunger'||id==='energy'){bar.style.background=v<25?'#cc7561':id==='energy'?'#d6ad61':'#8da76f'}}
function updateUI(){ui.day.textContent=state.day;let h=Math.floor(state.minute/60)%24,m=Math.floor(state.minute%60);ui.clock.textContent=`${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`;setMeter('health',state.health);setMeter('hunger',state.hunger);setMeter('energy',state.energy);setMeter('mood',state.mood);document.getElementById('mood-label').textContent=state.mood>70?'settled':state.mood>40?'a little tired':'worn out';renderInv();
 let bar=document.getElementById('quest-bar'),progress=document.getElementById('quest-progress');if(!state.camp){let n=Math.min(state.wood,4)+Math.min(state.stone,3);bar.style.width=(n/7*100)+'%';progress.textContent=`${n} / 7`;document.getElementById('quest-copy').textContent=`Gather 4 wood and 3 stone, then build your little camp.`;document.getElementById('quest-title').textContent='Make yourself at home';document.getElementById('quest-icon').textContent='⌂'}else{let n=state.day-1;bar.style.width=(Math.min(n,6)/6*100)+'%';progress.textContent=`${Math.min(n,6)} / 6`;document.getElementById('quest-copy').textContent='Keep your needs tended and enjoy six more little days in Fernwood.';document.getElementById('quest-title').textContent='Make this place yours';document.getElementById('quest-icon').textContent='✿'}
 document.getElementById('craft-btn').classList.toggle('disabled',state.camp||state.wood<4||state.stone<3);document.getElementById('eat-btn').classList.toggle('disabled',state.berries+state.mushroom<1);document.getElementById('rest-btn').classList.toggle('disabled',state.energy>95&&state.mood>95);
}
function interact(){const o=nearObject();if(!o){showToast('Nothing to gather here. Take a little wander.');return}if(o.type==='camp'){rest(true);return}let message='';switch(o.type){case'tree':state.wood+=2;o.alive=false;message='You gathered 2 wood. The forest will grow it back.';break;case'rock':state.stone+=1;o.alive=false;message='A good sturdy stone for your camp.';break;case'berry':state.berries+=2;o.alive=false;message='Sweet wild berries +2. You can eat them with 1.';break;case'mushroom':state.mushroom++;o.alive=false;message='A little forest mushroom +1.';break;case'log':state.wood++;o.alive=false;message='Found a fallen branch. +1 wood.';break;default:message='A lovely little flower. It smells like home.';state.mood=Math.min(100,state.mood+2);o.alive=false;setTimeout(()=>{o.alive=true},20000)}gatheredTotal++;updateUI();showToast(message)}
function eat(){if(state.berries>0){state.berries--;state.hunger=Math.min(100,state.hunger+27);state.mood=Math.min(100,state.mood+5);showToast('A handful of sweet berries. Better already.')}else if(state.mushroom>0){state.mushroom--;state.hunger=Math.min(100,state.hunger+19);state.mood=Math.min(100,state.mood+2);showToast('A savory mushroom. That hit the spot.')}else{showToast('No snacks in your pockets. Look for berry bushes.');return}updateUI()}
function rest(atCamp=false){if(atCamp){state.energy=Math.min(100,state.energy+45);state.mood=Math.min(100,state.mood+18);state.health=Math.min(100,state.health+12);showToast('A cozy rest by your camp. The fire crackles softly.')}else{state.energy=Math.min(100,state.energy+20);state.mood=Math.min(100,state.mood+6);showToast('You pause and take a slow, deep breath.')}updateUI()}
function craft(){if(state.camp){showToast('Your little camp is already home. Stay awhile.');return}if(state.wood<4||state.stone<3){showToast(`Need ${Math.max(0,4-state.wood)} more wood and ${Math.max(0,3-state.stone)} more stone.`);return}state.wood-=4;state.stone-=3;state.camp=true;state.mood=Math.min(100,state.mood+20);state.health=Math.min(100,state.health+10);showToast('You made a little camp. This place is yours now.');updateUI()}

function drawGround(){
 const left=Math.max(0,Math.floor(camera.x/TILE)-1),right=Math.min(MAP,Math.ceil((camera.x+W)/TILE)+2),top=Math.max(0,Math.floor(camera.y/TILE)-1),bottom=Math.min(MAP,Math.ceil((camera.y+H)/TILE)+2);
 for(let gy=top;gy<bottom;gy++)for(let gx=left;gx<right;gx++){let x=gx*TILE,y=gy*TILE;let v=rand(gx,gy,2),path=isPath(x+TILE/2,y+TILE/2);ctx.fillStyle=path?(v>.45?'#aa9b70':'#a3956b'):['#78976b','#7e9c70','#759268','#829d71','#78966d'][Math.floor(v*5)];ctx.fillRect(x,y,TILE+1,TILE+1);
   if(!path){ctx.fillStyle=v>.65?'#92aa7c44':'#4c734d20';ctx.fillRect(x+6+rand(gx,gy,9)*25,y+5+rand(gx,gy,10)*27,3,2);if(v>.88){ctx.fillStyle='#f0dc9c';ctx.fillRect(x+28,y+28,2,2)}}else{ctx.fillStyle='#c9b98635';ctx.fillRect(x+rand(gx,gy,4)*38,y+rand(gx,gy,5)*38,5,3)}
 }
 // Deep, softly edged ponds and their little shoreline.
 for(const p of ponds){ctx.beginPath();ctx.ellipse(p.x,p.y,p.rx+13,p.ry+12,-.15,0,Math.PI*2);ctx.fillStyle='#6b895e';ctx.fill();ctx.beginPath();ctx.ellipse(p.x,p.y,p.rx,p.ry,-.15,0,Math.PI*2);let g=ctx.createLinearGradient(p.x-p.rx,p.y-p.ry,p.x+p.rx,p.y+p.ry);g.addColorStop(0,'#6eaaa0');g.addColorStop(.55,'#59958d');g.addColorStop(1,'#477c79');ctx.fillStyle=g;ctx.fill();ctx.strokeStyle='#b8c89a';ctx.lineWidth=3;ctx.stroke();ctx.globalAlpha=.22;ctx.strokeStyle='#e3ead0';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(p.x-25+i*18,p.y-8+i*12,18+i*5,5,-.1,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1}
}
function drawTree(o){let s=o.scale,x=o.x,y=o.y;ctx.fillStyle='#334a3544';ctx.beginPath();ctx.ellipse(x,y+5,23*s,10*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#745b3e';ctx.fillRect(x-4*s,y-30*s,8*s,32*s);ctx.fillStyle='#547449';ctx.beginPath();ctx.arc(x,y-37*s,21*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#668654';ctx.beginPath();ctx.arc(x-9*s,y-45*s,15*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#78945f';ctx.beginPath();ctx.arc(x+5*s,y-50*s,12*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#829d69';ctx.beginPath();ctx.arc(x-3*s,y-54*s,8*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a8b77c88';ctx.beginPath();ctx.arc(x-10*s,y-48*s,4*s,0,Math.PI*2);ctx.fill()}
function drawRock(o){let s=o.scale,x=o.x,y=o.y;ctx.fillStyle='#3d4b4140';ctx.beginPath();ctx.ellipse(x,y+3,17*s,8*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#838a7b';ctx.beginPath();ctx.moveTo(x-15*s,y);ctx.lineTo(x-10*s,y-13*s);ctx.lineTo(x+2*s,y-18*s);ctx.lineTo(x+15*s,y-10*s);ctx.lineTo(x+17*s,y);ctx.closePath();ctx.fill();ctx.fillStyle='#a4aa98';ctx.beginPath();ctx.moveTo(x-10*s,y-13*s);ctx.lineTo(x+2*s,y-18*s);ctx.lineTo(x+4*s,y-8*s);ctx.lineTo(x-7*s,y-5*s);ctx.closePath();ctx.fill()}
function drawBerry(o){let s=o.scale,x=o.x,y=o.y;ctx.fillStyle='#40593b44';ctx.beginPath();ctx.ellipse(x,y+3,16*s,7*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#517a50';ctx.beginPath();ctx.arc(x,y-7*s,11*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#739663';ctx.beginPath();ctx.arc(x-7*s,y-10*s,7*s,0,Math.PI*2);ctx.arc(x+6*s,y-13*s,6*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bd6357';for(const [dx,dy] of [[-5,-8],[6,-7],[1,-15]]){ctx.beginPath();ctx.arc(x+dx*s,y+dy*s,3*s,0,Math.PI*2);ctx.fill()}}
function drawFlower(o){let x=o.x,y=o.y,s=o.scale;ctx.fillStyle='#55704e';ctx.fillRect(x,y-11*s,2*s,12*s);ctx.fillStyle=o.seed%2?'#f0d98f':'#e9c5b3';for(let i=0;i<5;i++){let a=i*6.28/5;ctx.beginPath();ctx.arc(x+Math.cos(a)*4*s,y-13*s+Math.sin(a)*4*s,2.4*s,0,6.28);ctx.fill()}ctx.fillStyle='#bd9c56';ctx.beginPath();ctx.arc(x,y-13*s,2*s,0,6.28);ctx.fill()}
function drawObject(o){if(!o.alive)return;switch(o.type){case'tree':drawTree(o);break;case'rock':drawRock(o);break;case'berry':drawBerry(o);break;case'mushroom':{let x=o.x,y=o.y,s=o.scale;ctx.fillStyle='#d9c9aa';ctx.fillRect(x-2*s,y-7*s,4*s,8*s);ctx.fillStyle='#b97563';ctx.beginPath();ctx.ellipse(x,y-8*s,8*s,5*s,0,Math.PI,0);ctx.fill();ctx.fillStyle='#fff0d6';ctx.fillRect(x-3*s,y-10*s,2*s,1.5*s);break}case'log':ctx.fillStyle='#765b43';ctx.beginPath();ctx.ellipse(o.x,o.y,13*o.scale,5*o.scale,-.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b39a70';ctx.beginPath();ctx.arc(o.x+10*o.scale,o.y+3*o.scale,4*o.scale,0,Math.PI*2);ctx.fill();break;case'flower':drawFlower(o)}}
function drawCamp(){if(!state.camp)return;let x=WORLD/2,y=WORLD/2;ctx.fillStyle='#3c493447';ctx.beginPath();ctx.ellipse(x,y+8,58,22,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a89770';ctx.beginPath();ctx.ellipse(x,y+2,46,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d6c9a8';ctx.beginPath();ctx.moveTo(x-28,y+1);ctx.lineTo(x-13,y-35);ctx.lineTo(x+11,y-35);ctx.lineTo(x+28,y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#8c9272';ctx.beginPath();ctx.moveTo(x-12,y+1);ctx.lineTo(x-13,y-35);ctx.lineTo(x+11,y-35);ctx.lineTo(x+13,y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#6f5c43';ctx.fillRect(x-5,y-3,10,5);ctx.fillStyle='#65472f';ctx.fillRect(x-3,y-17,6,18);ctx.fillStyle='#8c5534';ctx.fillRect(x-11,y+12,22,4);ctx.fillStyle='#b89d70';ctx.fillRect(x-9,y+8,18,4);if(state.minute%1440>1080||state.minute%1440<360){let glow=ctx.createRadialGradient(x+2,y+7,2,x+2,y+7,90);glow.addColorStop(0,'#f1bc6655');glow.addColorStop(1,'#f1bc6600');ctx.fillStyle=glow;ctx.fillRect(x-90,y-80,180,180)}ctx.fillStyle='#f4a44b';ctx.beginPath();ctx.ellipse(x+2,y+9,6,4,0,0,6.28);ctx.fill()}
function drawPlayer(now){let x=state.x,y=state.y;let moving=!!(keys.w||keys.a||keys.s||keys.d||keys.ArrowUp||keys.ArrowDown||keys.ArrowLeft||keys.ArrowRight||Object.values(touch).some(Boolean));let bob=moving?Math.sin(now/90)*1.8:Math.sin(now/420)*.7;ctx.fillStyle='#24342b44';ctx.beginPath();ctx.ellipse(x,y+4,11,5,0,0,6.28);ctx.fill();ctx.fillStyle='#d7b790';ctx.beginPath();ctx.arc(x,y-16+bob,7,0,6.28);ctx.fill();ctx.fillStyle='#604d3b';ctx.beginPath();ctx.arc(x,y-19+bob,7.2,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#587455';ctx.beginPath();ctx.moveTo(x-10,y-8+bob);ctx.quadraticCurveTo(x,y-13+bob,x+10,y-8+bob);ctx.lineTo(x+8,y+5+bob);ctx.quadraticCurveTo(x,y+9+bob,x-8,y+5+bob);ctx.closePath();ctx.fill();ctx.fillStyle='#d2bd8c';ctx.fillRect(x-5,y+4+bob,4,6);ctx.fillRect(x+2,y+4+bob,4,6);ctx.fillStyle='#493d32';ctx.fillRect(x-5,y+9+bob,5,2);ctx.fillRect(x+2,y+9+bob,5,2);ctx.fillStyle='#493c31';ctx.fillRect(x+2,y-17+bob,1.5,1.5)}
function drawCritters(dt){let night=state.minute%1440>1140||state.minute%1440<330;for(const c of critters){if(!c.alive)continue;let d=Math.hypot(c.x-state.x,c.y-state.y),safe=state.camp&&d<105;if(night&&!safe){let a=Math.atan2(state.y-c.y,state.x-c.x);if(d>30){c.x+=Math.cos(a)*dt*18;c.y+=Math.sin(a)*dt*18}if(d<25&&c.scared<=0){state.health=Math.max(0,state.health-.6);state.mood=Math.max(0,state.mood-.15);c.scared=2.2;showToast('A curious critter startled you. Try SPACE to shoo it!')}}if(c.scared>0)c.scared-=dt;let sx=c.x-camera.x,sy=c.y-camera.y;if(sx<-60||sy<-60||sx>W+60||sy>H+60)continue;ctx.fillStyle='#39403a44';ctx.beginPath();ctx.ellipse(c.x,c.y+3,12,4,0,0,6.28);ctx.fill();ctx.fillStyle=c.kind==='hare'?'#a6a18b':'#9b7955';ctx.beginPath();ctx.ellipse(c.x,c.y-5,10,6,-.12,0,6.28);ctx.fill();ctx.beginPath();ctx.arc(c.x+7,c.y-8,5,0,6.28);ctx.fill();if(c.kind==='hare'){ctx.beginPath();ctx.ellipse(c.x+6,c.y-16,2,7,-.2,0,6.28);ctx.ellipse(c.x+10,c.y-15,2,6,.2,0,6.28);ctx.fill()}ctx.fillStyle='#34392f';ctx.fillRect(c.x+9,c.y-9,1.5,1.5)}}
function draw(now,dt){if(!W||!H)return;camera.x=Math.max(0,Math.min(WORLD-W,state.x-W/2));camera.y=Math.max(0,Math.min(WORLD-H,state.y-H/2));ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-camera.x,-camera.y);drawGround();drawCamp();let visible=objects.filter(o=>o.alive&&o.x>camera.x-70&&o.x<camera.x+W+70&&o.y>camera.y-80&&o.y<camera.y+H+80);visible.sort((a,b)=>a.y-b.y);for(const o of visible)drawObject(o);drawCritters(dt);drawPlayer(now);
 const time=state.minute%1440,night=time<330||time>1140,twilight=(time>1050&&time<=1140)||(time>=300&&time<390);if(night||twilight){ctx.save();ctx.setTransform(dpr,0,0,dpr,0,0);let alpha=night?.31:.12;ctx.fillStyle=night?`rgba(20,34,58,${alpha})`:'rgba(168,105,73,.09)';ctx.fillRect(0,0,W,H);ctx.restore()}
 ctx.restore();let o=nearObject();if(o){let label=o.type==='tree'?'Gather wood':o.type==='rock'?'Gather stone':o.type==='berry'?'Pick berries':o.type==='mushroom'?'Pick mushroom':o.type==='log'?'Pick up branch':o.type==='camp'?'Rest at your camp':'Admire flower';ui.hint.innerHTML=`<span class="keycap">E</span> ${label}`;ui.hint.classList.add('show')}else ui.hint.classList.remove('show');let px=state.x,py=state.y;let region=Math.hypot(px-WORLD/2,py-WORLD/2)<250?'THE LITTLE MEADOW':px<WORLD*.45?'FERNWOOD · WESTERN TRAIL':px>WORLD*.7?'FERNWOOD · DEEP WOODS':'FERNWOOD · WILDERNESS';ui.location.textContent=region;
}

