const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const TILE=40,MAP=90,WORLD=MAP*TILE;
let W=0,H=0,dpr=1,camera={x:0,y:0},last=0,uiTime=0,toastTimer=0,gameOn=false,ended=false,keys={},touch={},objects=[],ponds=[],critters=[],gatheredTotal=0;
let state={x:WORLD/2,y:WORLD/2,day:1,minute:480,health:100,hunger:82,energy:92,mood:76,wood:0,stone:0,berries:2,mushroom:0,camp:false,played:0};
const rand=(x,y,s=0)=>{let n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n)};
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function makeWorld(){objects=[];critters=[];ponds=[{x:WORLD*.30,y:WORLD*.38,rx:160,ry:115},{x:WORLD*.69,y:WORLD*.65,rx:125,ry:155},{x:WORLD*.77,y:WORLD*.29,rx:85,ry:68}];
 const types=['tree','tree','tree','tree','rock','berry','berry','mushroom','flower','log'];
