function setMeter(id,value){const v=Math.max(0,Math.min(100,value));document.getElementById(id+'B').style.width=v+'%';document.getElementById(id+'V').textContent=Math.round(v)+'%';if(id==='hunger'||id==='energy')document.getElementById(id+'B').style.background=v<25?'#cc7561':id==='energy'?'#d6ad61':'#8da76f'}
